That doesn't align with my experience. Both shared and unshared informers suffer the same issue. The issue comes down to `processorListener` which is used by all informers; `processorListener.add()` is async. If it wasn't, then everything would work fine actually (that is, `HasSynced` would also mean "event handlers have seen initial state", not just the store). This is why "Option 1: Make processorListener synchronous" in https://github.com/kubernetes/kubernetes/issues/113763 resolves the issue (although its probably a bad idea)

Here is a test of both shared and unshared that can reproduce it. Note its flaky - fails about 1% of the timer on my machine, so you need to run it with `stress` or similar.

<details>

```go
package main

import (
	"fmt"
	"sync/atomic"
	"testing"
	"time"

	v1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/util/wait"
	"k8s.io/client-go/informers"
	informersv1 "k8s.io/client-go/informers/core/v1"
	"k8s.io/client-go/kubernetes/fake"
	"k8s.io/client-go/tools/cache"
)

func TestInformerUnshared(t *testing.T) {
	kc := fake.NewSimpleClientset(pods...)
	handled := &atomic.Int32{}
	podInformer := informersv1.NewFilteredPodInformer(kc, "", 0, cache.Indexers{cache.NamespaceIndex: cache.MetaNamespaceIndexFunc}, nil)
	podInformer.AddEventHandler(cache.ResourceEventHandlerFuncs{
		AddFunc: func(obj any) {
			handled.Add(1)
		},
	})

	stop := make(chan struct{})
	go podInformer.Run(stop)
	WaitForCacheSync(stop, podInformer.HasSynced)

	if h := handled.Load(); h != int32(len(pods)) {
		t.Fatalf("got %+v events, expected %v", h, len(pods))
	}
}

func TestInformerShared(t *testing.T) {
	kc := fake.NewSimpleClientset(pods...)
	informers := informers.NewSharedInformerFactory(kc, 0)
	handled := &atomic.Int32{}
	podInformer := informers.Core().V1().Pods().Informer()
	podInformer.AddEventHandler(cache.ResourceEventHandlerFuncs{
		AddFunc: func(obj any) {
			handled.Add(1)
		},
	})

	stop := make(chan struct{})
	informers.Start(stop)
	WaitForInformerFactorySync(stop, informers)
	WaitForCacheSync(stop, podInformer.HasSynced)

	if h := handled.Load(); h != int32(len(pods)) {
		t.Fatalf("got %+v events, expected %v", h, len(pods))
	}
}

func WaitForInformerFactorySync(stop <-chan struct{}, informerFactory informers.SharedInformerFactory) {
	returnImmediately := make(chan struct{})
	close(returnImmediately)
	_ = wait.PollImmediate(time.Microsecond*10, wait.ForeverTestTimeout, func() (bool, error) {
		select {
		case <-stop:
			return false, fmt.Errorf("channel closed")
		default:
		}
		for _, synced := range informerFactory.WaitForCacheSync(returnImmediately) {
			if !synced {
				return false, nil
			}
		}
		return true, nil
	})
}

// Like standard WaitForCacheSync but more aggressive, to more easily detect race conditions.
func WaitForCacheSync(stop <-chan struct{}, cacheSyncs ...cache.InformerSynced) bool {
	max := time.Millisecond * 100
	delay := time.Millisecond
	f := func() bool {
		for _, syncFunc := range cacheSyncs {
			if !syncFunc() {
				return false
			}
		}
		return true
	}
	for {
		select {
		case <-stop:
			return false
		default:
		}
		res := f()
		if res {
			return true
		}
		delay *= 2
		if delay > max {
			delay = max
		}
		time.Sleep(delay)
	}
}

